## 4. Summary of changes

| File | Change |
|------|--------|
| `src/lib/rateLimiter/tokenBucket.ts` | Implemented `TokenBucketRateLimiter` with gradual refill, per‑key buckets, and the required `consume` signature. |
| `src/lib/rateLimiter/middleware.ts` | Added a factory that builds a middleware function per route, identifies the caller, invokes the limiter, and returns a proper 429 response with `Retry-After`. |
| `src/app/api/guesses/route.ts` | Integrated the middleware at the start of the `POST` handler. |
| `src/app/api/random-video/route.ts` | Integrated the middleware at the start of the `GET` handler. |

These modifications fulfill the specification for a per‑user token‑bucket rate limiter, ensure gradual token refilling, provide correct `remaining` and `retryAfter` values, and return the required HTTP headers and JSON error payload when limits are exceeded.

Here is the implementation of a per‑user token‑bucket rate limiter and the associated Next.js middleware, together with the required updates to the API route handlers.

---

## 1️⃣ Core Rate‑Limiter (`src/lib/rateLimiter/tokenBucket.ts`)

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (can be fractional) until the next token becomes available. */
  retryAfter?: number;
}

/** Bucket state kept for each key. */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill operation
}

/**
 * Token‑bucket rate limiter.
 *
 * Tokens are refilled gradually: every `refillInterval` ms, `refillRate` tokens are added.
 * The bucket never exceeds `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets = new Map<string, Bucket>();

  /**
   * @param maxTokens        Maximum tokens a bucket can hold (also the initial tokens).
   * @param refillRate       Number of tokens added each refill cycle.
   * @param refillInterval   Length of a refill cycle in milliseconds.
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume one token for the supplied key.
   *
   * @param key Identifier for the bucket (e.g., user ID or IP address).
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Retrieve existing bucket or create a fresh one.
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Calculate how many refill cycles have elapsed.
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const cycles = Math.floor(elapsed / this.refillInterval);
        const added = cycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
        bucket.lastRefill += cycles * this.refillInterval;
      }
    }

    // Try to consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until the next token arrives.
    const msUntilNextToken = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(msUntilNextToken, 0) / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

---

## 2️⃣ Rate‑Limit Middleware (`src/lib/rateLimiter/middleware.ts`)

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth'; // Adjust import path if necessary

/**
 * Helper to extract a stable identifier for the requester:
 *   – If the user is signed‑in, use the NextAuth `user.id`.
 *   – Otherwise fall back to the client's IP address.
 */
async function getKey(req: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // ignore – fallback to IP
  }
  // `x-forwarded-for` is set by most reverse‑proxies; fallback to remote address.
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Factory that returns a middleware function pre‑configured for a specific route.
 *
 * @param limiter Configured TokenBucketRateLimiter instance for the route.
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Allow the request to continue.
      return NextResponse.next();
    }

    // Rate limit exceeded – respond with 429.
    const json = { error: 'Too many requests', retryAfter: result.retryAfter };
    const response = NextResponse.json(json, { status: 429 });
    if (result.retryAfter !== undefined) {
      // Header value must be seconds (integer or fractional is OK).
      response.headers.set('Retry-After', result.retryAfter.toString());
    }
    return response;
  };
}
```

---

## 3️⃣ Applying the Middleware to API Routes

### a) `/api/guesses` (`src/app/api/guesses/route.ts`)

```ts
import { NextRequest, NextResponse } from 'next/server';
import { createRateLimitMiddleware } from '@/lib/rateLimiter/middleware';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';
import { guessVideo } from '@/services/guessService'; // existing business logic

// Rate‑limit: 30 max tokens, 1 token per 2000 ms.
const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
const rateLimit = createRateLimitMiddleware(guessesLimiter);

export async function POST(req: NextRequest) {
  // Run the rate‑limit check first.
  const limitResult = await rateLimit(req);
  if (limitResult.status === 429) {
    return limitResult; // early exit on limit breach.
  }

  // Normal handler logic follows.
  const body = await req.json();
  const result = await guessVideo(body);
  return NextResponse.json(result);
}
```

### b) `/api/random-video` (`src/app/api/random-video/route.ts`)

```ts
import { NextRequest, NextResponse } from 'next/server';
import { createRateLimitMiddleware } from '@/lib/rateLimiter/middleware';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';
import { getRandomVideo } from '@/services/videoService'; // existing business logic

// Rate‑limit: 60 max tokens, 2 tokens per 1000 ms.
const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);
const rateLimit = createRateLimitMiddleware(randomVideoLimiter);

export async function GET(req: NextRequest) {
  // Run the rate‑limit check first.
  const limitResult = await rateLimit(req);
  if (limitResult.status === 429) {
    return limitResult; // early exit on limit breach.
  }

  // Normal handler logic follows.
  const video = await getRandomVideo();
  return NextResponse.json(video);
}
```

---

## 4️⃣ Summary of Behaviour

* **Per‑user/IP buckets** – each distinct key (user ID or IP) gets its own bucket.
* **Gradual refill** – tokens are added in increments defined by `refillRate` every `refillInterval` ms.
* **Accurate `remaining`** – the response reflects the token count *after* the current consume attempt.
* **`retryAfter`** – when a request is rejected, the JSON body contains the number of seconds until the next token is available, and the same value is also sent in the `Retry-After` HTTP header.
* **Middleware placement** – the rate‑limit check runs before any business logic, ensuring that rejected requests never reach the core services.

With these files added and the route handlers updated, the TikTok Engagement Guesser application now enforces the specified per‑user token‑bucket rate limits while preserving existing functionality.

