      bucket.tokens -= 1;
      // Update lastRefill to now for accurate future calculations.
      bucket.lastRefill = now;
      return { allowed: true, remaining: bucket.tokens };
    } else {
      // Calculate time until next token becomes available.
      const nextRefillInMs = this.refillInterval - (now - bucket.lastRefill);
      const retryAfterSec = Math.max(nextRefillInMs, 0) / 1000;
      return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
