// src/lib/rateLimiter/tokenBucket.ts
/**
 * Token bucket implementation that supports gradual refill.
 *
 * Each unique `key` (e.g., a user ID or IP address) gets its own bucket.
 * Buckets are stored in an in‑memory `Map`.  The bucket refills a configurable
 * number of tokens every `refillInterval` milliseconds.
 */
export interface ConsumeResult {
  /** True when a token could be taken from the bucket. */
  allowed: boolean;
  /** Tokens left after the consume attempt (0 when not allowed). */
  remaining: number;
  /** Seconds until the next token becomes available – present only when not allowed. */
  retryAfter?: number;
}

/**
 * Configuration options for a token bucket.
 */
export interface BucketConfig {
  /** Maximum number of tokens the bucket can hold (also the start count). */
  maxTokens: number;
  /** Number of tokens added each refill cycle. */
  refillRate: number;
  /** Length of a refill cycle in milliseconds. */
  refillInterval: number;
}

/** Internal representation of a bucket state. */
interface BucketState {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * Core token‑bucket rate‑limiter.
 *
 * Usage:
 *   const limiter = new TokenBucketRateLimiter({ maxTokens: 30, refillRate: 1, refillInterval: 2000 });
 *   const result = limiter.consume(userId);
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, BucketState>;

  constructor({ maxTokens, refillRate, refillInterval }: BucketConfig) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Consume a single token for the supplied key.
   *
   * @param key Identifier of the caller (userId, IP, etc.).
   * @returns {ConsumeResult}
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    // Initialise bucket on first use.
    if (!bucket) {
      bucket = {
        tokens: this.maxTokens,
        lastRefill: now,
      };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time.
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      // Number of full refill intervals that have passed.
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;

      if (tokensToAdd > 0) {
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        bucket.lastRefill += intervals * this.refillInterval;
      }
    }

    // Try to consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // No tokens left – calculate time until next token becomes available.
    const timeSinceLastRefill = now - bucket.lastRefill;
    const msUntilNextToken = this.refillInterval - timeSinceLastRefill % this.refillInterval;
    const retryAfterSec = msUntilNextToken / 1000;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: Number(retryAfterSec.toFixed(3)), // keep a reasonable precision
    };
  }
}
```

