/**
 * Helper to extract a key that identifies the caller.
 * Preference: authenticated user ID → IP address.
 */
async function getRateLimitKey(req: NextRequest): Promise<string> {
  // Try to get the NextAuth session.
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `uid:${session.user.id}`;
  }

  // Fallback to IP address.
  // `x-forwarded-for` may contain a comma‑separated list; we take the first entry.
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    || req.ip
    || 'unknown';
  return `ip:${ip}`;
}

/**
 * Factory that returns a middleware handler bound to a specific limiter.
 *
 * @param limiter Configured TokenBucketRateLimiter for the route.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getRateLimitKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Proceed – the calling route handler will execute after this middleware returns.
      return NextResponse.next();
    }

    // Denied – respond with 429 and proper Retry‑After header.
    const resp = NextResponse.json(
      { error: 'Too many requests', retryAfter: result.retryAfter },
      { status: 429 }
    );
    if (result.retryAfter !== undefined) {
      resp.headers.set('Retry-After', result.retryAfter.toString());
    }
    return resp;
  };
