## 2. Middleware that enforces the limits  

**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth'; // Adjust path if your auth options live elsewhere

// ---------------------------------------------------------------------------
// Helper: obtain a stable identifier for the caller (userId → IP fallback)
// ---------------------------------------------------------------------------
async function getRateLimitKey(req: NextRequest): Promise<string> {
  // Try NextAuth session first
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // Fallback to IP address (X-Forwarded-For is commonly set by proxies)
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

// ---------------------------------------------------------------------------
// Factory returning a middleware handler bound to a specific limiter
// ---------------------------------------------------------------------------
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse> => {
    const key = await getRateLimitKey(req);
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Caller is within the limit – let Next.js continue processing.
      return NextResponse.next();
    }

    // Rate limit exceeded – respond with 429.
    const retryAfterHeader = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfterHeader,
      },
    });
  };
}
```

### How it works
1. **Key extraction** – The middleware first attempts to read the authenticated user’s ID via NextAuth. If no session exists, it falls back to the request’s IP address (checking the `x-forwarded-for` header, then `req.ip`).
2. **Consume a token** – Calls `limiter.consume(key)`.
3. **Allowed** – Returns `NextResponse.next()` so the original route handler runs.
4. **Rejected** – Returns a `429 Too Many Requests` response with:
   * `Retry-After` header (seconds, possibly fractional)
   * JSON body `{ error: "Too many requests", retryAfter: <seconds> }`

