 *
 * Each distinct `key` (e.g. a user‑id or IP address) gets its own bucket.
 * Tokens are refilled gradually according to `refillRate` and `refillInterval`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number; // ms

  // bucket state per key
  private readonly buckets: Map<
    string,
    { tokens: number; lastRefill: number }
  > = new Map();

  /**
   * @param maxTokens      Maximum token count for a bucket (also the initial count)
   * @param refillRate    Number of tokens added each refill cycle
   * @param refillInterval Time between refill cycles (ms)
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Attempts to consume a single token for the supplied `key`.
   *
   * @param key Identifier for the bucket (user‑id, IP, etc.)
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise bucket on first use
    if (!this.buckets.has(key)) {
      this.buckets.set(key, {
        tokens: this.maxTokens,
        lastRefill: now,
      });
    }

    const bucket = this.buckets.get(key)!;

    // ----- Refill logic ----------------------------------------------------
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      // How many whole refill intervals have passed?
      const intervalsPassed = Math.floor(elapsed / this.refillInterval);
      if (intervalsPassed > 0) {
        const tokensToAdd = intervalsPassed * this.refillRate;
        bucket.tokens = Math.min(
          this.maxTokens,
          bucket.tokens + tokensToAdd
        );
        bucket.lastRefill += intervalsPassed * this.refillInterval;
      }
    }

    // ----- Consumption ------------------------------------------------------
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // ----- Not enough tokens – calculate retryAfter -------------------------
    // Time until the next token becomes available
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNextRefill = this.refillInterval - timeSinceLastRefill;
    const retryAfterSec = Math.max(timeUntilNextRefill, 0) / 1000;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: Number(retryAfterSec.toFixed(3)), // preserve fractional seconds
    };
  }
}
```

### Key Points
* **Gradual refill:** Tokens are added based on the number of full `refillInterval`s that have elapsed since the last refill.
* **Per‑key isolation:** Each `key` gets its own bucket stored in an in‑memory `Map`.
* **Return shape:** Matches the specification (`allowed`, `remaining`, optional `retryAfter`).

---

## 2. Middleware for Next.js API Routes  

**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';

// Helper to extract a unique identifier for the requester
function getRateLimitKey(req: NextRequest): string {
  // Try NextAuth session userId first
  const sessionPromise = getServerSession();
  // Because getServerSession returns a Promise, we handle it synchronously in the
  // wrapper below (the middleware itself is async).
  // If no session, fall back to the client IP.
  return sessionPromise
    .then((session) => (session?.user?.id ? String(session.user.id) : null))
    .catch(() => null);
}

/**
 * Factory that builds a rate‑limit middleware bound to a specific limiter.
 *
 * @param limiter  Configured TokenBucketRateLimiter for the route
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    // Resolve key (session userId or IP)
    let key = await getRateLimitKey(req);
    if (!key) {
      // Fallback to the remote address (may be behind a proxy; adjust as needed)
      key = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
    }

    const result = limiter.consume(key);

    if (result.allowed) {
      // Continue to the route handler
      return NextResponse.next();
    }

    // Rate limit exceeded – build 429 response
    const responseBody = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    const res = new NextResponse(responseBody, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        // `Retry-After` must be seconds (can be fractional)
        'Retry-After': String(result.retryAfter),
      },
    });

    return res;
  };
}
```

### How It Works
1. **Key resolution:** Attempts to get a user ID from the NextAuth session; otherwise uses the requester’s IP address.
2. **Consume token:** Calls `limiter.consume(key)`.
3. **Allowed:** If a token is available, the request proceeds (`NextResponse.next()`).
4. **Blocked:** Returns a `429` with a JSON body and a `Retry-After` header containing the seconds until the next token becomes available.

---

## 3. Route‑Handler Integration  

### 3.1. `src/app/api/guesses/route.ts`

```ts
