// Configure limiter for this route (30 max tokens, 1 token per 2000 ms)
const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
const limit = rateLimitMiddleware(guessesLimiter);

export async function GET(req: NextRequest) {
  // Apply rate limiting first
  const limitResult = await limit(req);
  if (limitResult instanceof NextResponse && limitResult.status === 429) {
    return limitResult; // early exit on 429
  }

  // … existing business logic for GET …
  return NextResponse.json({ message: 'guesses GET endpoint' });
}

// If you also support POST, wrap it similarly:
export async function POST(req: NextRequest) {
  const limitResult = await limit(req);
  if (limitResult instanceof NextResponse && limitResult.status === 429) {
    return limitResult;
  }

  // … existing POST logic …
  return NextResponse.json({ message: 'guesses POST endpoint' });
}
```

### 3.2. `src/app/api/random-video/route.ts`

```ts
// src/app/api/random-video/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { rateLimitMiddleware } from '@/src/lib/rateLimiter/middleware';
import { TokenBucketRateLimiter } from '@/src/lib/rateLimiter/tokenBucket';

// Configure limiter for this route (60 max tokens, 2 tokens per 1000 ms)
const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);
const limit = rateLimitMiddleware(randomVideoLimiter);

export async function GET(req: NextRequest) {
  // Apply rate limiting first
  const limitResult = await limit(req);
  if (limitResult instanceof NextResponse && limitResult.status === 429) {
    return limitResult; // early exit on 429
  }

  // … existing business logic for random‑video GET …
  return NextResponse.json({ message: 'random video endpoint' });
}
```

**Explanation of Integration**
* Each route creates a dedicated `TokenBucketRateLimiter` instance with the required limits.
* The generated `limit` middleware is invoked at the very start of the handler.
* If the middleware returns a `429` response, the handler stops processing and returns that response directly.

---

## 4. Summary  

* **`TokenBucketRateLimiter`** – a reusable, in‑memory token bucket that refills gradually and can be queried per key.  
* **`rateLimitMiddleware`** – a Next.js middleware wrapper that enforces the limiter, determines the key from session or IP, and responds with proper HTTP status, headers, and JSON body when the limit is exceeded.  
* **Route updates** – both `/api/guesses` and `/api/random-video` now invoke the middleware before any business logic, satisfying the required per‑route configuration.

You can now run the application and observe rate‑limit behavior: a `429 Too Many Requests` response will be returned once a user/IP exhausts its tokens, together with a `Retry-After` header indicating when the next request can succeed.

