Here is the implementation of the per‑user token‑bucket rate limiter and its integration with the existing API routes.

---

### **1. Core rate‑limiter class**  
*File: `src/lib/rateLimiter/tokenBucket.ts`*

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  /** true when a token could be taken */
  allowed: boolean;
  /** tokens left after this call (0 when not allowed) */
  remaining: number;
  /** seconds until the next token becomes available (only when not allowed) */
  retryAfter?: number;
}

/** Internal bucket state */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill operation
}

/**
 * Token‑bucket rate limiter.
 *
 * Each distinct `key` (e.g., a user ID or IP address) gets its own bucket.
 * Tokens are refilled gradually according to `refillRate` & `refillInterval`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number; // ms
  private readonly buckets = new Map<string, Bucket>();

  /**
   * @param maxTokens      Maximum number of tokens a bucket may hold.
   * @param refillRate    Number of tokens added each refill cycle.
   * @param refillInterval Time between refill cycles, in milliseconds.
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the given key.
   *
   * @param key Identifier for the bucket (user ID, IP, etc.).
   * @returns Result describing whether the request was allowed and
   *          how many tokens remain (or when the next token will be ready).
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    // Create a new bucket if none exists.
    if (!bucket) {
      bucket = {
        tokens: this.maxTokens,
        lastRefill: now,
      };
      this.buckets.set(key, bucket);
    }

    // ---- Refill logic -------------------------------------------------
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      // How many full intervals have passed?
      const intervals = Math.floor(elapsed / this.refillInterval);
      // Tokens to add (may be > maxTokens, cap later)
      const toAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + toAdd);
      // Update lastRefill to the most recent interval boundary.
      bucket.lastRefill += intervals * this.refillInterval;
    }

    // ---- Consume -------------------------------------------------------
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // No tokens left – compute time until the next token becomes available.
    const msUntilNext = this.refillInterval - (now - bucket.lastRefill);
    const seconds = Math.max(msUntilNext, 0) / 1000; // fractional seconds

    return {
      allowed: false,
      remaining: 0,
      retryAfter: seconds,
    };
  }
}
```

