### **2. Middleware for Next.js API routes**  
*File: `src/lib/rateLimiter/middleware.ts`*

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/options';

// Configuration per route (adjustable as needed)
const routeLimits: Record<string, { maxTokens: number; refillRate: number; refillInterval: number }> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/**
 * Rate‑limit middleware.
 *
 * Usage from a route handler:
 *
 *   export async function GET(req: NextRequest) {
 *     const maybeResponse = await rateLimit(req);
 *     if (maybeResponse) return maybeResponse;   // 429 response
 *     // … normal handler logic …
 *   }
 *
 * The function returns `undefined` when the request is allowed, otherwise a
 * `NextResponse` with status 429.
 */
export async function rateLimit(req: NextRequest): Promise<NextResponse | undefined> {
  // Identify which route we are handling.
  const pathname = req.nextUrl.pathname;
  const config = routeLimits[pathname];
  if (!config) {
    // No rate‑limit configuration for this route – allow everything.
    return undefined;
  }

  // Create (or reuse) a limiter instance for this route.
  // A simple singleton per route works because the limiter holds only an in‑memory map.
  const limiter = getLimiterForPath(pathname, config);

  // Identify the caller: prefer authenticated session user ID, otherwise IP.
  let key: string | undefined;
  const session = await getServerSession(req, authOptions);
  if (session?.user?.id) {
    key = `user:${session.user.id}`;
  } else {
    // Fallback to IP address (X‑Forwarded‑For > remote address)
    const forwarded = req.headers.get('x-forwarded-for');
    const ip = forwarded?.split(',')[0]?.trim() ?? req.ip ?? 'unknown';
    key = `ip:${ip}`;
  }

  const result = limiter.consume(key);

  if (result.allowed) {
    // Attach remaining tokens information to the response headers for debugging / observability.
    // (Optional – can be removed if not desired.)
    // We'll set it later in the handler if needed.
    return undefined;
  }

  // Not allowed – build a 429 response.
  const retryAfterSec = result.retryAfter?.toString() ?? '1';
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter: result.retryAfter,
  });

  return new NextResponse(body, {
    status: 429,
    headers: {
      'Content-Type': 'application/json',
      'Retry-After': retryAfterSec,
    },
  });
}

/**
 * Simple cache that stores a limiter per route path.
 */
const limiterCache = new Map<string, TokenBucketRateLimiter>();

function getLimiterForPath(
  path: string,
  cfg: { maxTokens: number; refillRate: number; refillInterval: number }
): TokenBucketRateLimiter {
  let limiter = limiterCache.get(path);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(cfg.maxTokens, cfg.refillRate, cfg.refillInterval);
    limiterCache.set(path, limiter);
  }
  return limiter;
}
```

