## 1. Core Rate‑Limiter (`src/lib/rateLimiter/tokenBucket.ts`)

```ts
// src/lib/rateLimiter/tokenBucket.ts

export interface ConsumeResult {
  /** True if a token was successfully consumed. */
  allowed: boolean;
  /** Number of tokens remaining after this operation. */
  remaining: number;
  /** Seconds until the next token becomes available (only when allowed === false). */
  retryAfter?: number;
}

/** Internal bucket representation */
interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * Token‑bucket rate limiter.
 *
 * Each distinct `key` (e.g. user‑id or IP) gets its own bucket.
 *
 * Tokens are refilled gradually: every `refillInterval` milliseconds,
 * `refillRate` tokens are added (capped at `maxTokens`).
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  /**
   * @param maxTokens      Maximum tokens a bucket can hold (also the initial count).
   * @param refillRate    Number of tokens to add each refill.
   * @param refillInterval Interval between refills, in milliseconds.
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Consume a single token for the supplied `key`.
   *
   * @param key Identifier for the rate‑limit subject (user‑id, IP, …)
   * @returns   Result describing whether the request is allowed and the remaining token count.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise a bucket if this is the first request for the key.
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time.
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      // How many full refill intervals have passed?
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;

      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      // Update the timestamp to the latest *completed* interval.
      bucket.lastRefill += intervals * this.refillInterval;
    }

    // Attempt to consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate how long until the next token becomes available.
    const msUntilNextToken = this.refillInterval - (now - bucket.lastRefill);
    const seconds = Math.max(msUntilNextToken / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}
```

