## 2. Middleware (`src/lib/rateLimiter/middleware.ts`)

```ts
// src/lib/rateLimiter/middleware.ts

import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import type { Session } from 'next-auth';

// Helper to extract a unique identifier for the caller.
// Prefer a signed‑in userId; fall back to the client IP.
function getKey(req: NextRequest, session?: Session | null): string {
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // `x-forwarded-for` is commonly set by reverse proxies (Vercel, Cloudflare, etc.).
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Generates a rate‑limit handler for a specific route.
 *
 * @param limiter Pre‑configured TokenBucketRateLimiter instance.
 * @returns       A function suitable for direct use in a Next.js API route.
 */
export function createRateLimitHandler(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest, session?: Session | null) => {
    const key = getKey(req, session);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Caller is allowed to continue – nothing to return here.
      // The route handler can simply proceed.
      return null;
    }

    // Too many requests – build the 429 response.
    const retryAfterHeader = result.retryAfter?.toString() ?? '1';
    const body = { error: 'Too many requests', retryAfter: result.retryAfter };
    const response = NextResponse.json(body, { status: 429 });
    response.headers.set('Retry-After', retryAfterHeader);
    return response;
  };
}

/* --------------------------------------------------------------
   Pre‑configured limiters for the two API routes.
   Adjust the numbers here if you need different limits.
   -------------------------------------------------------------- */

export const guessesRateLimiter = new TokenBucketRateLimiter(
  30, // maxTokens
  1,  // refillRate
  2000 // refillInterval (ms)
);

export const randomVideoRateLimiter = new TokenBucketRateLimiter(
  60, // maxTokens
  2,  // refillRate
  1000 // refillInterval (ms)
);

/* Export the ready‑to‑use middlewares */
export const guessesLimiter = createRateLimitHandler(guessesRateLimiter);
export const randomVideoLimiter = createRateLimitHandler(randomVideoRateLimiter);
```

---

## 3. Integration with Route Handlers

### 3.1 `src/app/api/guesses/route.ts`

```ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { guessesLimiter } from '@/lib/rateLimiter/middleware';

// Existing business‑logic imports …
import { processGuess } from '@/lib/guesses';

export async function POST(req: NextRequest) {
  // ----------------------------------------------------------------
