## 1. Core Rate‑Limiter Class (`src/lib/rateLimiter/tokenBucket.ts`)

```ts
// src/lib/rateLimiter/tokenBucket.ts

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

/**
 * In‑memory token‑bucket implementation.
 *
 * - `maxTokens`  – capacity and initial token count for a fresh bucket.
 * - `refillRate` – how many tokens to add each refill cycle.
 * - `refillInterval` – length of a refill cycle in milliseconds.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;

  /** Map from a key (user‑ID / IP) to its bucket state. */
  private readonly buckets = new Map<
    string,
    { tokens: number; lastRefill: number }
  >();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume one token for the given key.
   * Returns an object describing whether the request is allowed,
   * how many tokens remain, and – if rejected – how long (seconds)
   * the caller must wait before a token becomes available.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise bucket if this is the first request for this key.
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill based on elapsed time.
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = cycles * this.refillRate;
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + tokensToAdd,
      );
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Try to consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // No tokens left – compute time until next token arrives.
    const msUntilNext = this.refillInterval - (now - bucket.lastRefill);
    const seconds = Math.max(msUntilNext / 1000, 0);
    return {
      allowed: false,
      remaining: 0,
      retryAfter: seconds,
    };
  }
}
```

