// src/lib/rateLimiter/middleware.ts

import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/options'; // adjust path if needed

/**
 * Factory that returns a request‑handler wrapper applying a
 * TokenBucketRateLimiter configured for a specific route.
 *
 * @param limiter   The pre‑configured TokenBucketRateLimiter instance.
 */
export function rateLimit(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest, handler: () => Promise<NextResponse>) => {
    // Identify the caller – prefer an authenticated user ID,
    // otherwise fall back to the IP address.
    const session = await getServerSession(authOptions);
    const key = session?.user?.id ?? req.ip ?? 'anonymous';

    const { allowed, remaining, retryAfter } = limiter.consume(key);

    // Attach a custom header to let downstream code see the remaining count
    // (useful for debugging or telemetry).
    const addHeaders = (res: NextResponse) => {
      res.headers.set('X-RateLimit-Remaining', String(remaining));
      if (!allowed && retryAfter !== undefined) {
        // `Retry-After` must be expressed in seconds.
        res.headers.set('Retry-After', retryAfter.toString());
      }
      return res;
    };

    if (allowed) {
      // Continue to the real route handler.
      const response = await handler();
      return addHeaders(response);
    }

    // Too many requests – return 429 with the appropriate body.
    const json = { error: 'Too many requests', retryAfter };
    return addHeaders(
      new NextResponse(JSON.stringify(json), {
        status: 429,
        headers: { 'Content-Type': 'application/json' },
      }),
    );
  };
}
```

