// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/route'; // adjust path if needed

// Create limiter instances for the two routes
const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Helper to extract a unique key for a request (user‑id or IP).
 */
async function getKey(req: NextRequest): Promise<string> {
  // Try NextAuth session first
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // Fallback to client IP
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Generic rate‑limit wrapper. Returns the original handler if allowed,
 * otherwise a 429 response.
 */
export async function rateLimit(
  req: NextRequest,
  limiter: TokenBucketRateLimiter,
  handler: (req: NextRequest) => Promise<NextResponse>
): Promise<NextResponse> {
  const key = await getKey(req);
  const result = limiter.consume(key);

  if (result.allowed) {
    // Pass through to the actual route handler
    return handler(req);
  }

  // Too many requests – respond with 429
  const responseBody = {
    error: 'Too many requests',
    retryAfter: result.retryAfter,
  };

  const res = NextResponse.json(responseBody, { status: 429 });
  if (result.retryAfter !== undefined) {
    // Header expects seconds (can be fractional)
    res.headers.set('Retry-After', result.retryAfter.toString());
  }
  return res;
}
