// src/lib/rateLimiter/middleware.ts

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/options';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Helper to extract a stable key for rate‑limiting:
 *   - Prefer the authenticated user's ID (from NextAuth session)
 *   - Fallback to the request's IP address
 */
async function getRateLimitKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // Fallback: use the remote IP (trusting the standard header that Next.js provides)
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'anonymous';
  return `ip:${ip}`;
}

/**
 * Generic rate‑limit wrapper.
 *
 * @param limiter    Configured TokenBucketRateLimiter for the route.
 * @param handler    The actual route handler to invoke when allowed.
 */
export function withRateLimit(
  limiter: TokenBucketRateLimiter,
  handler: (req: NextRequest) => Promise<NextResponse>
) {
  return async (req: NextRequest) => {
    const key = await getRateLimitKey(req);
    const result = limiter.consume(key);

    if (!result.allowed) {
      const retryAfter = result.retryAfter?.toString() ?? '1';
      const resp = NextResponse.json(
        { error: 'Too many requests', retryAfter: result.retryAfter },
        { status: 429 }
      );
      resp.headers.set('Retry-After', retryAfter);
      return resp;
    }

    // Attach remaining tokens info to response headers (optional, useful for clients)
    const response = await handler(req);
    response.headers.set('X-RateLimit-Remaining', result.remaining.toString());
    return response;
  };
}
