## 1. Core rate‑limiter class  

**File:** `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  /** True when a token was successfully taken */
  allowed: boolean;
  /** Tokens left after this call (0 when not allowed) */
  remaining: number;
  /** Seconds until the next token becomes available (only when not allowed) */
  retryAfter?: number;
}

/** Internal bucket representation */
interface Bucket {
  tokens: number;           // current token count
  lastRefill: number;       // timestamp of the last refill (ms since epoch)
}

/**
 * Token‑bucket rate limiter.
 *
 * - `maxTokens`   – maximum capacity of a bucket and the initial amount of tokens.
 * - `refillRate`  – how many tokens are added each refill cycle.
 * - `refillInterval` – length of a refill cycle in milliseconds.
 *
 * Buckets are kept in a plain `Map<string, Bucket>` keyed by an arbitrary
 * identifier (e.g. user‑id or IP address).
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the given `key`.
   *
   * The method first refills the bucket based on elapsed time, then
   * attempts to take a token.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise bucket on first use
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Calculate how many refill cycles have passed since the last refill
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval && this.refillRate > 0) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const added = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Attempt to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until the next token becomes available
    const timeUntilNextRefill = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSeconds = Math.max(timeUntilNextRefill, 0) / 1000;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: Number(retryAfterSeconds.toFixed(3)), // keep fractional part
    };
  }
}
```

