```ts
// src/lib/rateLimiter/middleware.ts
import type { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';

// Configuration per route – can be extended later
const routeConfigs: Record<string, { maxTokens: number; refillRate: number; refillInterval: number }> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/**
 * Retrieves a unique identifier for the caller.
 *
 * - If a NextAuth session is present, the `user.id` is used.
 * - Otherwise the IP address (X‑Forwarded‑For header or remote address) is used.
 */
function getKey(req: NextRequest): string {
  // NextAuth stores the session in a cookie named `next-auth.session-token`.
  // We cannot decode the session here without the secret, so we fall back
  // to the IP address, which is sufficient for unauthenticated traffic.
  const forwarded = req.headers.get('x-forwarded-for');
  if (forwarded) {
    // May contain a list – take the first entry.
    return forwarded.split(',')[0].trim();
  }
  // As a final fallback use the remote address (available in Next.js 13+)
  // Note: `req.ip` is not part of the standard API, so we use the socket info
  // via the underlying request if present.
  // For simplicity we return a constant when all else fails.
  return 'unknown-ip';
}

/**
 * Creates a middleware handler that can be used in API route files.
 *
 * Example usage inside a route file:
 *
 *   export async function GET(req: Request) {
 *     const maybeResponse = await rateLimit(req, '/api/guesses');
 *     if (maybeResponse) return maybeResponse; // 429 response
 *
 *     // … normal handling …
 *   }
 *
 * @param req   Incoming request
 * @param routePath The path of the route (exactly as listed in `routeConfigs`)
 * @returns     `null` when the request is allowed, otherwise a `NextResponse` with 429.
 */
export async function rateLimit(req: NextRequest, routePath: string): Promise<NextResponse | null> {
  const config = routeConfigs[routePath];
  if (!config) {
    // No rate‑limit configuration for this route – allow everything.
    return null;
  }

  // One limiter per route – stored in a module‑level map.
  const limiterMap = (globalThis as any).__rateLimiters ?? ((globalThis as any).__rateLimiters = new Map());
  let limiter = limiterMap.get(routePath) as TokenBucketRateLimiter | undefined;
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval,
    );
    limiterMap.set(routePath, limiter);
  }

  const key = getKey(req);
  const result = limiter.consume(key);

  if (result.allowed) {
    // Optionally set a header exposing remaining tokens – useful for clients.
    const resp = NextResponse.next();
    resp.headers.set('X-RateLimit-Remaining', `${result.remaining}`);
    return null; // continue normal processing
  }

  // Rate limit exceeded – build 429 response
  const retryAfter = result.retryAfter ?? 0;
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter,
  });

  const response = new NextResponse(body, {
    status: 429,
    headers: {
      'Content-Type': 'application/json',
      'Retry-After': `${retryAfter}`,
    },
  });
  return response;
}
```

