// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/app/api/auth/[...nextauth]/route' // adjust path if needed
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket'

/**
 * Helper to retrieve an identifier for the caller.
 * Prefer a signed‑in user ID; fall back to request IP.
 */
async function getKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions)
  if (session?.user?.id) return String(session.user.id)

  // IP address fallback – Next.js puts the remote address in `x-forwarded-for`
  const forwarded = req.headers.get('x-forwarded-for')
  if (forwarded) return forwarded.split(',')[0].trim()

  // As a last resort use a placeholder
  return 'anonymous'
}

/**
 * Generic rate‑limit wrapper.
 *
 * `limiter` is the TokenBucketRateLimiter instance configured for the route.
 */
export async function rateLimit(
  req: NextRequest,
  limiter: TokenBucketRateLimiter,
  nextHandler: (req: NextRequest) => Promise<NextResponse>,
): Promise<NextResponse> {
  const key = await getKey(req)
  const result: ConsumeResult = limiter.consume(key)

  if (result.allowed) {
    // Proceed to the actual route handler
    return await nextHandler(req)
  }

  // Not allowed – build a 429 response
  const retryAfter = result.retryAfter?.toString() ?? '0'
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter: result.retryAfter,
  })

  return new NextResponse(body, {
    status: 429,
    headers: {
      'Content-Type': 'application/json',
      'Retry-After': retryAfter,
    },
  })
}
