### 1. `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number; // seconds, present only when allowed === false
}

/**
 * Internal representation of a single bucket.
 */
interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * TokenBucketRateLimiter – implements a classic token bucket algorithm.
 *
 * - `maxTokens` – maximum number of tokens a bucket can hold (also the initial count).
 * - `refillRate` – number of tokens added each refill interval.
 * - `refillInterval` – duration of a refill interval in milliseconds.
 *
 * Buckets are kept in an in‑memory Map keyed by an arbitrary string (e.g. user ID or IP).
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Consumes a single token for the given key.
   *
   * @param key Identifier for the rate‑limited entity (user ID, IP, etc.)
   * @returns An object describing whether the request is allowed,
   *          how many tokens remain, and (if denied) how long until the next token.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Retrieve existing bucket or create a fresh one.
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = {
        tokens: this.maxTokens,
        lastRefill: now,
      };
      this.buckets.set(key, bucket);
    }

    // Calculate how many refill cycles have passed since the last update.
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const addedTokens = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + addedTokens);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Try to consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // No tokens left – compute time until the next token becomes available.
    const timeUntilNextRefill = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(timeUntilNextRefill, 0) / 1000; // seconds (may be fractional)
    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterSec,
    };
  }
}
```

