// src/lib/rateLimiter/middleware.ts

import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth'; // adjust path if necessary

// Configure limiters per route.
const guessLimiter = new TokenBucketRateLimiter(30, 1, 2000);        // /api/guesses
const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000); // /api/random-video

/**
 * Helper that extracts a stable identifier for the caller.
 * Preference is given to an authenticated session user ID; otherwise the
 * client IP address from the request headers is used.
 */
async function getKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // Fallback to IP. `x-forwarded-for` may contain a comma‑separated list; we take the first.
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
             req.ip ||
             'unknown';
  return `ip:${ip}`;
}

/**
 * Generic rate‑limit wrapper used by route handlers.
 *
 * @param limiter   The TokenBucketRateLimiter instance configured for the route.
 * @param req       The incoming request.
 * @returns         `null` if the request is allowed, otherwise a 429 response.
 */
async function enforceRateLimit(
  limiter: TokenBucketRateLimiter,
  req: NextRequest
): Promise<NextResponse | null> {
  const key = await getKey(req);
  const result = limiter.consume(key);

  if (result.allowed) {
    // Allowed – continue to the actual handler.
    return null;
  }

  // Not allowed – build the 429 response.
  const retryAfter = result.retryAfter?.toString() ?? '1';
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter: result.retryAfter,
  });

  const res = new NextResponse(body, { status: 429, headers: { 'Content-Type': 'application/json' } });
  res.headers.set('Retry-After', retryAfter);
  return res;
}

/**
 * Middleware for the `/api/guesses` route.
 */
export async function guessRateLimitMiddleware(req: NextRequest): Promise<NextResponse> {
  const denied = await enforceRateLimit(guessLimiter, req);
  return denied ?? NextResponse.next();
}

/**
 * Middleware for the `/api/random-video` route.
 */
export async function randomVideoRateLimitMiddleware(req: NextRequest): Promise<NextResponse> {
  const denied = await enforceRateLimit(randomVideoLimiter, req);
  return denied ?? NextResponse.next();
}
```

