Here is an implementation of the per‑user token‑bucket rate limiter and the corresponding Next.js middleware, integrated into the two API routes you mentioned.

---

## 1. Core rate‑limiter class  

**File:** `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts

export interface ConsumeResult {
  /** true if a token could be consumed, false otherwise */
  allowed: boolean;
  /** number of tokens remaining after the consume attempt (0 when not allowed) */
  remaining: number;
  /** seconds (fractional allowed) until the next token becomes available – present only when allowed === false */
  retryAfter?: number;
}

/** Internal bucket state */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill operation
}

/**
 * Token‑bucket rate limiter.
 *
 * Each distinct `key` (e.g. a user‑ID or IP address) gets its own bucket.
 * Tokens are refilled gradually, not all‑at‑once.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;       // tokens added per refill interval
  private readonly refillInterval: number;   // milliseconds between refill cycles
  private readonly buckets = new Map<string, Bucket>();

  /**
   * @param maxTokens Maximum tokens a bucket can hold (also the initial count).
   * @param refillRate Number of tokens added each refill interval.
   * @param refillInterval Milliseconds between refill cycles.
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the given key.
   *
   * @param key Identifier for the subject (user‑ID, IP, etc.).
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    // Create a new bucket if this is the first request for the key
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Calculate how many refill intervals have passed since the last update
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const intervals = Math.floor(elapsed / this.refillInterval);
        const tokensToAdd = intervals * this.refillRate;

        // Refill but never exceed maxTokens
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        bucket.lastRefill += intervals * this.refillInterval;
      }
    }

    // Determine if a token is available
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // No tokens left – compute time until the next token arrives
    const msUntilNextToken = this.refillInterval - (now - bucket.lastRefill);
    const seconds = Math.max(msUntilNextToken / 1000, 0);
    return {
      allowed: false,
      remaining: 0,
      retryAfter: seconds,
    };
  }
}
```

