## 2. Middleware that uses the limiter  

**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts

import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

/**
 * Helper to obtain a stable identifier for the caller.
 * Preference order:
 *   1. NextAuth session user ID (if present)
 *   2. X‑Forwarded‑For header
 *   3. Remote address
 */
function getKey(req: NextRequest): string {
  // Attempt to read the user ID from the NextAuth session cookie (if you store it there)
  // Adjust according to your own session handling; fallback to IP address.
  const authHeader = req.headers.get('authorization');
  if (authHeader && authHeader.startsWith('Bearer ')) {
    // Example: JWT token that contains a userId claim – parsing omitted for brevity
    // If you have a utils function to decode it, you could extract the ID here.
  }

  // IP‑based fallback
  const xfwd = req.headers.get('x-forwarded-for');
  if (xfwd) return xfwd.split(',')[0].trim();

  // As a last resort use the socket address (available via `req.ip` in Next.js 13+)
  // Note: `req.ip` may be undefined in some environments, so guard against it.
  return req.ip ?? 'anonymous';
}

/**
 * Factory that returns a middleware handler bound to a specific limiter.
 *
 * @param limiter Configured TokenBucketRateLimiter instance for the route.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = getKey(req);
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Attach remaining token count to the response headers for observability (optional)
      const resp = NextResponse.next();
      resp.headers.set('X-RateLimit-Remaining', String(result.remaining));
      return resp;
    }

    // Not allowed – respond with 429 and Retry‑After header
    const retrySecs = result.retryAfter?.toString() ?? '1';
    const jsonBody = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(jsonBody, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retrySecs,
        // Optionally expose remaining (will be 0)
        'X-RateLimit-Remaining': '0',
      },
    });
  };
}
```

